import{_ as d,o as s,c as a,a3 as e}from"./chunks/framework.BwzYn71E.js";const m=JSON.parse('{"title":"","description":"","frontmatter":{"translationSource":{"title":"萌新入坑流程及注意事项「武陵篇」","archivedAt":"2026-10-31","url":"https://docs.qq.com/aio/DTmluZ1diWlpQZldw?p=L0hsh88XqUwFigit3JjUTg","scope":"page"},"translationLang":"zh","head":[["link",{"rel":"canonical","href":"https://kokobird28144.github.io/endfield-skydoc/zh/new-player-progression-and-precautions-wuling"}],["link",{"rel":"alternate","hreflang":"en","href":"https://kokobird28144.github.io/endfield-skydoc/new-player-progression-and-precautions-wuling"}],["link",{"rel":"alternate","hreflang":"zh-CN","href":"https://kokobird28144.github.io/endfield-skydoc/zh/new-player-progression-and-precautions-wuling"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://kokobird28144.github.io/endfield-skydoc/new-player-progression-and-precautions-wuling"}]]},"headers":[],"relativePath":"zh/new-player-progression-and-precautions-wuling.md","filePath":"zh/page-L0hsh88XqUwFigit3JjUTg.md"}'),i={name:"zh/new-player-progression-and-precautions-wuling.md"};function c(p,t,r,l,o,n){return s(),a("div",null,[...t[0]||(t[0]=[e('<div class="logistics-content"><h1 id="萌新入坑流程及注意事项「武陵篇」" tabindex="-1">萌新入坑流程及注意事项「武陵篇」 <a class="header-anchor" href="#萌新入坑流程及注意事项「武陵篇」" aria-label="Permalink to &quot;萌新入坑流程及注意事项「武陵篇」&quot;">​</a></h1><blockquote><p>源页面 ID：<code>L0hsh88XqUwFigit3JjUTg</code> ｜ <a href="https://docs.qq.com/aio/DTmluZ1diWlpQZldw?p=L0hsh88XqUwFigit3JjUTg" target="_blank" rel="noreferrer">在腾讯文档中打开</a></p></blockquote><p><span class="mark-grey"><em>观前提醒：由于速通玩家和养老玩家在武陵地区的体验天差地别，速通玩法的流程安排及资源分配十分紧张，而养老玩法压力很小不做赘述，本篇旨在帮助速通玩家合理安排入坑流程以及资源利用。</em></span></p><p><span id="source-block-8umcWj3tmbjudi7FUj2RZm"></span></p><h3 id="第零阶段-进入武陵前的预备知识" tabindex="-1">第零阶段：进入武陵前的预备知识 <a class="header-anchor" href="#第零阶段-进入武陵前的预备知识" aria-label="Permalink to &quot;第零阶段：进入武陵前的预备知识&quot;">​</a></h3><p>1.开号进入游戏后会有一段固定剧情，按照引导完成即可。解锁活动系统后，会有特殊活动“主线先行解锁：武陵”，接取任务即可直接进入武陵地区。</p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-6141527773096cad.q90-531f0ac7ce0f246c.webp" alt="萌新入坑流程及注意事项「武陵篇」"></p><p>2.武陵的主线任务为：景玉谷→武陵城→清波寨→首墩→应龙关→北部禁区→祀的画，其余地区均为支线地图。</p><p>3.本文提供的所有蓝图需要接水，沉积酸，惰气，息壤气。接口都在明显位置用准入口做了标签，除了特殊说明外，每个准入口对应一个水/沉积酸泵。蓝图做了大量防呆设计，不建议私自改动。</p><p>4.过任务的时候尽可能多的在地图上收集采录桩，积累工业点数。如果收集的点数不宽裕，请务必按照每阶段图示解锁，否则即使拍下蓝图也无法使用，甚至损坏蓝图中某些设备的出口设置！</p><p>5.前期调度券极其紧张，每一笔收入都要花在刀刃上，不要花在刀背，刀把，刀鞘上！升级解锁的优先级如下图，红色为优先，黄色次优先，绿色再次，其余部分按价格从低到高陆续升级即可。</p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-52d2854c15711ddd.q90-f6dcfe0cf2495fe3.webp" alt="萌新入坑流程及注意事项「武陵篇」"></p><div class="logistics-image-caption" data-source-block="mj0Hgpc1UecOGUlkDmaFqK"><p>区域解锁升级及设施解锁升级优先级</p></div><p>6.速通玩家的各个节点的任务进度、建设等级、矿物产出、注意事项如下图所示。本篇涉及到的所有蓝图均对应当前进度的最低矿物产出，不会出现矿物产出供不应求的现象。</p><p>7.注意，<span class="mark-red">本攻略一共涉及11张蓝图</span>，由于各个阶段蓝图全部为嵌入式增量蓝图，需要分取或填补前一阶段阶段产线，所以请确保前一阶段蓝图完整且没有被改动！否则可能会出现蓝图无法放置，或可以放置但无法运行的情况。</p><p>8.篇为基建教学，基建外内容非必要不做赘述。</p><p>9.虽然跳过四号谷地进入武陵时会在武陵地区直接解锁谷地科技，并给我们谷地科技解锁的设备各50个，但仓库取货口依然不够用，而且制作仓库取货口所需要的紫晶矿只在四号谷地产出。尽管四号谷地的主线引导要我们制作紫晶零件，但从引导流程上看：前期需要我们用便携式采矿机放在枢纽区基地南侧的源矿上，掏出源矿，塞进通电的精炼炉，生产晶体外壳提交任务。很可能有萌新如法炮制：便携矿机插在基地西侧紫晶矿→手掏紫晶矿→塞进精炼炉产紫晶纤维→掏出紫晶纤维塞进配件机产紫晶零件......所以请在最迟第五阶段前，在四号谷地放置紫晶零件产线，用于必需设备的生产！</p><p>10.截止2026年10月30日，本套蓝图制作和测试时间超过1个月，目前没出过问题，如果有问题可以在群聊内交流，只要我在有问必答。</p><p><span id="source-block-zyNrWvjZ8IZLxWcFn70ZSH"></span></p><h3 id="第一阶段-主线推完武陵城-解锁武陵基地-天王坪据点" tabindex="-1">第一阶段：主线推完武陵城（解锁武陵基地，天王坪据点） <a class="header-anchor" href="#第一阶段-主线推完武陵城-解锁武陵基地-天王坪据点" aria-label="Permalink to &quot;第一阶段：主线推完武陵城（解锁武陵基地，天王坪据点）&quot;">​</a></h3><p>需要拉完景玉谷及武陵城的全部矿点，矿物的产出达到源矿250/min，蓝铁矿60/min，建设等级达到2级；顺手在基底周围获取仅1颗即可的必需植物；工业点开启图中5个；在任务中有解锁环境监测站（无需调度券），同时接到拍摄任务，获得第一桶金——12500调度券！这笔调度券需要解锁武陵城基地的存取线，在武陵城基地拍下第一张蓝图，准入口接上两个水泵，用于前期启动。</p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-a66295804b10cfd6.q90-d4558e8f7a7f4071.webp" alt="萌新入坑流程及注意事项「武陵篇」"></p><div class="logistics-image-caption" data-source-block="GeNpI8CQpEYcS7V56O8qnD"><p>第一颗植物点位</p></div><p><img src="/endfield-skydoc/logistics/src/assets/images/img-a84175f2bcee0dbe.q90-aed8151b3ff9fbb5.webp" alt="萌新入坑流程及注意事项「武陵篇」"></p><div class="logistics-image-caption" data-source-block="Si42vhFo8IGriYXHo4ZZMC"><p>工业点解锁</p></div><p><img src="/endfield-skydoc/logistics/src/assets/images/img-41e6d85e352201de.q90-9ac91b83eb8cd2bf.webp" alt="萌新入坑流程及注意事项「武陵篇」"></p><div class="logistics-image-caption" data-source-block="eDIJ4SQYWfU78yh0MwiVKO"><p>武陵城区域解锁</p></div><p><img src="/endfield-skydoc/logistics/src/assets/images/img-533d9c5f18ebaf92.q90-3a397532af36ba06.webp" alt="萌新入坑流程及注意事项「武陵篇」"></p><div class="logistics-image-caption" data-source-block="bSoYZwaunxj0CLhCXCzNCG"><p>武陵城蓝图</p></div><p><span class="mark-blue">[一阶段-武陵] EF01Oe4582508IoO9oe4</span></p><p>武陵城：河道在左，拍下蓝图<span class="mark-blue">[一阶段-武陵]</span>，消耗180/min源矿，60/min蓝铁矿；仓库里只需要有一颗芽针及一颗砂叶就可以。启动阶段在仓库中囤积约325芽针，325砂叶，3250蓝铁零件，3250息壤；达到稳定后产出6/min低容武陵电池，3/min芽针针剂，常态1800总发电量。</p><p>然后继续过任务……</p><p><span id="source-block-vMNBmjr3Ce6UXxKUoVtfzH"></span></p><h3 id="第二阶段-主线推完首墩-解锁首墩据点" tabindex="-1">第二阶段：主线推完首墩（解锁首墩据点） <a class="header-anchor" href="#第二阶段-主线推完首墩-解锁首墩据点" aria-label="Permalink to &quot;第二阶段：主线推完首墩（解锁首墩据点）&quot;">​</a></h3><p>需要拉满矿点，记得补充武陵城、景玉谷新形成的矿点，矿物产出为源矿360/min，蓝铁矿90/min，赤铜矿120/min，建设等级达到5级；工业点开启图中4个；武陵基地需要扩展一次面积，增加一次基段，所需的调度券获取方法按难易程度提供：</p><ol class="logistics-tutorial-steps"><li value="1">据点解锁就会提供一半上限的调度券囤积，兑换电池/药即可获得；</li><li value="2">武陵环境监测除主线提供的一单，还有一个价值54000调度券的任务，在指定位置拍照即可；</li><li value="3">武陵右下角的仓储节点需12500调度券解锁，可以接取3次11w＋调度券的订单，但由于耗时费力，不推荐。</li></ol><p><img src="/endfield-skydoc/logistics/src/assets/images/img-79516508bbbf67c6.q90-0d29767163042fe8.webp" alt="萌新入坑流程及注意事项「武陵篇」"></p><div class="logistics-image-caption" data-source-block="0QbriENSePo5uDSJRFmo5h"><p>工业点解锁</p></div><p><img src="/endfield-skydoc/logistics/src/assets/images/img-bbf00d1d6c435f3c.q90-6d1ee1b0dabbaf4c.webp" alt="萌新入坑流程及注意事项「武陵篇」"></p><div class="logistics-image-caption" data-source-block="Qorex3Hz6jJlYCBDqxaDVY"><p>武陵区域扩大、存取线增加</p></div><p><img src="/endfield-skydoc/logistics/src/assets/images/img-e84a6b10561216d0.q90-75a37eab97234e8c.webp" alt="萌新入坑流程及注意事项「武陵篇」"></p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-94df1e587c326e5a.jpeg" alt="萌新入坑流程及注意事项「武陵篇」"></p><div class="logistics-image-caption" data-source-block="gcojM9LeIYvPpDqpaZB6GC"><p>2阶段蓝图</p></div><p><span class="mark-blue">[二阶段-武陵1] EF014AE2IO21I3i3E71A</span></p><p><span class="mark-blue">[二阶段-武陵2] EF014AE2IO21I309E71A</span></p><p>武陵城：将第一张蓝图选中移到基地左上方，下方拼接<span class="mark-blue">[二阶段-武陵1] </span>，右上方拼接<span class="mark-blue">[二阶段-武陵2] </span>，左侧重新接好6个水泵即可。启动后囤积3250个赤铜零件；稳定后，基建一共提供每分钟8.75低容电池，6优质芽针针剂，4.5芽针针剂，常态3400发电（轻微波动，不影响产线），可以满足三个据点全部升2级前的调度券兑换。</p><p><span id="source-block-kq2WoDKmVzCIvmtd0NmIX9"></span></p><h3 id="第三阶段-主线推完北部禁区-解锁应龙关据点" tabindex="-1">第三阶段：主线推完北部禁区（解锁应龙关据点） <a class="header-anchor" href="#第三阶段-主线推完北部禁区-解锁应龙关据点" aria-label="Permalink to &quot;第三阶段：主线推完北部禁区（解锁应龙关据点）&quot;">​</a></h3><p>需要拉完矿点和气点，矿产为360/min源矿，90/min蓝铁矿，220/min赤铜矿，30/min息壤气，建设等级达到7级；工业点除炮台和需要「再引春来」任务解锁的12天有烘炉以外，全部都需要解锁；首墩需要解锁存取线，应龙关需要解锁存取线。</p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-89f51652e86641df.q90-dcb1e298e5831f63.webp" alt="萌新入坑流程及注意事项「武陵篇」"></p><div class="logistics-image-caption" data-source-block="8ZjoJLuQLXZkaUpEYilnQq"><p>工业点解锁</p></div><p><img src="/endfield-skydoc/logistics/src/assets/images/img-75c143b0a487b178.q90-3bbc8c8d92504ec1.webp" alt="萌新入坑流程及注意事项「武陵篇」"></p><div class="logistics-image-caption" data-source-block="h8RPifLjRreztPqmsx8qG0"><p>首墩区域解锁</p></div><p><img src="/endfield-skydoc/logistics/src/assets/images/img-3d8a536056c6db92.q90-2c563c4f5a335a93.webp" alt="萌新入坑流程及注意事项「武陵篇」"></p><div class="logistics-image-caption" data-source-block="C7hnmMcWHbVLX8LOvLGZ9K"><p>应龙关区域解锁，红色为必选，蓝色为按需选择</p></div><p><img src="/endfield-skydoc/logistics/src/assets/images/img-e93ca7dd9cc5e63b.q90-289dda5ce67397d5.webp" alt="萌新入坑流程及注意事项「武陵篇」"></p><div class="logistics-image-caption" data-source-block="iOnDBt3AOeaEYOEMV42sN2"><p>首墩蓝图</p></div><p><span class="mark-blue">[三阶段-首墩] EF012UOEu5E6u844eIOo</span></p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-b57acb48b18ea5c2.q90-918a808d3419fe0b.webp" alt="萌新入坑流程及注意事项「武陵篇」"></p><div class="logistics-image-caption" data-source-block="CkoiAg2Xgay1SvT0ANuqlG"><p>应龙关蓝图</p></div><p><span class="mark-blue">[三阶段-应龙1] EF01E75O34O93o0e3uIa</span></p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-3eaac66097f02ecc.q90-ead9e0cac784d135.webp" alt="萌新入坑流程及注意事项「武陵篇」"></p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-b3f46f89ecca6ac7.q90-bd25add93deffe16.webp" alt="萌新入坑流程及注意事项「武陵篇」"></p><div class="logistics-image-caption" data-source-block="RYhgMWylwrTNFFKDovOK6S"><p>应龙关补充蓝图</p></div><p><span class="mark-blue">[三阶段-应龙2] EF015i24oE4aou61eIoe</span></p><p>首墩：水池在左下角，酸池在下方，拍下蓝图<span class="mark-blue">[三阶段-首墩]</span>，接入5个水泵（可能会出现管道长度上限问题，可以在区域外接任意管道物流，如管道桥），惰气（80/min）。，接入5个水泵（可能会出现管道长度上限问题，可以在区域外接任意管道物流，如管道桥），惰气（80/min）。</p><p>应龙关：天师桩/空地在下方，拍下蓝图<span class="mark-blue">[三阶段-应龙1]</span>，左侧接入惰气（≥80/min），两个水泵，一个酸泵，一个息壤气（后续的「填隙驻地」解锁息壤气、雪松林息壤气，从下至上依次接入），右侧有12/min液化息壤输出口用于填隙驻地任务。</p><p>如果觉得速度太慢，可以扩张一次基地面积，原蓝图不动，拍下第二张蓝图<span class="mark-blue">[三阶段-应龙2]</span>，左上角接入一个水泵，再接入暗管输出42/min液化息壤，任务共有5处各需要5000单位的液化息壤的点位，每处大约2h完成。</p><p>蓝图启动后囤积325个蓝铁瓶装液化重息壤；稳定后，基建一共提供每分钟8.75低容电池，6优质芽针针剂，4.5芽针针剂，6重息壤。</p><p><span id="source-block-pugiJMZLp9hN1B6JlOQMK7"></span></p><h3 id="第四阶段-完成支线地图-藏剑谷-实验园区-雪松林-北部禁区「填隙驻地」-并解锁部分设施" tabindex="-1">第四阶段：完成支线地图（藏剑谷，实验园区，雪松林，北部禁区「填隙驻地」）并解锁部分设施 <a class="header-anchor" href="#第四阶段-完成支线地图-藏剑谷-实验园区-雪松林-北部禁区「填隙驻地」-并解锁部分设施" aria-label="Permalink to &quot;第四阶段：完成支线地图（藏剑谷，实验园区，雪松林，北部禁区「填隙驻地」）并解锁部分设施&quot;">​</a></h3><p>需要解锁或升级价格为10w调度券及以下的设施，拉完矿点和气点，矿产为500/min源矿，90/min蓝铁矿，330/min赤铜矿，120/min息壤气，建设等级达到10级；工业点除炮台以外，全部都需要解锁；武陵基地需要扩展一次面积（到最大80*80区域），首墩需要增加一次存取线；扩展到最大面积，应龙关需要扩大一次面积<span class="mark-red">（上一阶段使用补充蓝图扩大过一次的不需要再扩大！）</span></p><p>如果各地区区域解锁后，没有足够的调度券解锁升级设施，此时矿产为380/min源矿，90/min蓝铁矿，310/min赤铜矿，120/min息壤气，建设等级达到7级，可以先不拍应龙关蓝图，待达到矿产标准后再拍下应龙关蓝图。</p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-fa822810c7b2a8d2.q90-803d0604a51badb7.webp" alt="萌新入坑流程及注意事项「武陵篇」"></p><div class="logistics-image-caption" data-source-block="RPmScpfrjRjEHAiOkDHVzy"><p>工业点解锁</p></div><p><img src="/endfield-skydoc/logistics/src/assets/images/img-684b31d86fc52b8e.q90-b6a8741f01dcf9ba.webp" alt="萌新入坑流程及注意事项「武陵篇」"></p><div class="logistics-image-caption" data-source-block="7ygNDsu0npxoYGhJCffswv"><p>武陵城区域解锁</p></div><p><img src="/endfield-skydoc/logistics/src/assets/images/img-d6f9e49310d11d13.q90-a72a291feba9107b.webp" alt="萌新入坑流程及注意事项「武陵篇」"></p><div class="logistics-image-caption" data-source-block="8n8d5UQWgzWrzL54jSoUVg"><p>首墩区域解锁</p></div><p><img src="/endfield-skydoc/logistics/src/assets/images/img-24fb880d6bcaccbf.q90-cf2ebf2d97486d37.webp" alt="萌新入坑流程及注意事项「武陵篇」"></p><div class="logistics-image-caption" data-source-block="dnfYBb9YFzosg3iYyuOEJU"><p>应龙关区域解锁</p></div><p><img src="/endfield-skydoc/logistics/src/assets/images/img-332a94579c1bbfc3.q90-b9a3d15d5b65bbc1.webp" alt="萌新入坑流程及注意事项「武陵篇」"></p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-631f56ad99eba4ce.q90-9345fc62f8949550.webp" alt="萌新入坑流程及注意事项「武陵篇」"></p><div class="logistics-image-caption" data-source-block="8lr8MQsaPtT2GKC9pY7Gua"><p>武陵城蓝图</p></div><p><span class="mark-blue">[四阶段-武陵] EF01Oe4582508IIi9oe4</span></p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-e0eec934d65c2653.q90-1b75d548aa58e23d.webp" alt="萌新入坑流程及注意事项「武陵篇」"></p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-824a3366d29819a9.q90-e616d1ce3695acdb.webp" alt="萌新入坑流程及注意事项「武陵篇」"></p><div class="logistics-image-caption" data-source-block="notL0qhYdL1lDqkfqFXzej"><p>首墩蓝图</p></div><p><span class="mark-blue">[四阶段-首墩] EF016u09Aa94A79oO83e</span></p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-55f155da3237f9b2.q90-27c3735bed818abc.webp" alt="萌新入坑流程及注意事项「武陵篇」"></p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-c82394544de47e8e.q90-e701c578fdb1852e.webp" alt="萌新入坑流程及注意事项「武陵篇」"></p><div class="logistics-image-caption" data-source-block="AbyvJbqbN9hWfNlEk0n6J0"><p>应龙关蓝图</p></div><p><span class="mark-blue">[四阶段-应龙] EF01ao61e91OeAeaou5e</span></p><p>武陵城：河道在下方，在上方拍下蓝图<span class="mark-blue">[四阶段-武陵] </span>，右侧接入两个水泵，左上的未连接暗管连接净水节点，或连接4个废水处理机。<span class="mark-red">（视角有变化，截图截错了）</span></p><p>首墩：水池在左下，水标签左侧的水管（含物流）删掉，只保留原始30×30蓝图，将原有30×30部分挪到左下角，拍下蓝图<span class="mark-blue">[四阶段-首墩]</span>，接好左侧的5水泵和惰气，接好下方4水泵和1沉积酸。如果是删除了原有基建并重新放置上一阶段的首墩蓝图，需要等待旧蓝图重新暖机（约5分钟），在放置本阶段蓝图。</p><p>应龙关：天师桩在下，拍下上一阶段补充蓝图<span class="mark-red">（若上一阶段已经拍下则不需要这一步！）</span>，拍下本阶段蓝图<span class="mark-blue">[四阶段-应龙] </span>。</p><p>蓝图稳定后，基建一共提供每分钟5.75低容电池，6优质芽针针剂，4.5芽针针剂，自适应18-34.5重息壤，6灼铜零件。此时若删掉首墩的一个热能池，即可在1.6版本毕业，后续内容为产能补充，确保产能充足，及部分产物囤积用于装备制造、任务提交、防停产亏损等。</p><p><span id="source-block-4qawSeWZPB4KZUPWeOghF4"></span></p><h3 id="第五阶段-解锁并升级几乎所有设施-据点等级几乎全部为4级" tabindex="-1">第五阶段：解锁并升级几乎所有设施，据点等级几乎全部为4级 <a class="header-anchor" href="#第五阶段-解锁并升级几乎所有设施-据点等级几乎全部为4级" aria-label="Permalink to &quot;第五阶段：解锁并升级几乎所有设施，据点等级几乎全部为4级&quot;">​</a></h3><p><span class="mark-red">注意！本阶段刚需四号谷地产线！详情见第零阶段预备知识9。</span></p><p>需要解锁并升级几乎所有设施，据点等级几乎全部为4级，拉完矿点和气点，矿产为510/min源矿，120/min蓝铁矿，540/min赤铜矿，150/min息壤气。武陵城需要增加一次基段。</p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-dce0f990580d95c9.q90-e79f6eaf9b930c5d.webp" alt="萌新入坑流程及注意事项「武陵篇」"></p><div class="logistics-image-caption" data-source-block="JcbJMi79pp3HlhqTpRtFW2"><p>武陵城区域解锁</p></div><p><img src="/endfield-skydoc/logistics/src/assets/images/img-313161c5fd1bc860.q90-425a83273725b72e.webp" alt="萌新入坑流程及注意事项「武陵篇」"></p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-fad031d8e83d56ab.q90-4f86ad1b19958d83.webp" alt="萌新入坑流程及注意事项「武陵篇」"></p><div class="logistics-image-caption" data-source-block="W8SImq6joKJdEGQFfIokue"><p>武陵城蓝图[五阶段-武陵]</p></div><p><span class="mark-blue">[五阶段-武陵] EF01U9e72i7u2Oo37Oa8</span></p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-6d5d6b876752182f.q90-ed72f3c4d3605e7c.webp" alt="萌新入坑流程及注意事项「武陵篇」"></p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-45cdc9c36a7d7443.q90-fc69ab05322c515e.webp" alt="萌新入坑流程及注意事项「武陵篇」"></p><div class="logistics-image-caption" data-source-block="8zRNlEtAIcK3IRFuavOgvl"><p>首墩蓝图</p></div><p><span class="mark-blue">[五阶段-首墩] EF01u2836o3A6054AoOU</span></p><p>武陵城：河道在下，在右上角拍下蓝图<span class="mark-blue">[五阶段-武陵]</span>，右侧接入4个水泵，上方两个未连接暗管接入三级净水节点的新增的两个污水处理口。</p><p>首墩：水池在左下角，右上角拍下蓝图<span class="mark-blue">[五阶段-首墩]</span>。<span class="mark-red">（注意，由于首墩管道物流压力非常大，如果需要放置此蓝图，请确保基建之外管道物流不多于6个）</span></p><p>蓝图稳定后，基建一共提供每分钟5.75低容电池，6优质芽针针剂，4.5芽针针剂，自适应18-34.5重息壤，12灼铜零件，4,5中容武陵电池。预测可以毕业武陵最终版本的调度券兑换，无需继续放置多余基建。</p><p><span class="mark-green">在本阶段，基建分已经大毕业，但由于是一摆到底蓝图，多达6种产物，在据点兑换调度券时需要频繁切换产物。如果想要更高产能，或每个据点对话固定产物的基建可以更换喜欢的基建套餐，例如本文档中的最大毛产、最大净产、本人制作的其他基建作业（发布在B站）、团队以外的B站up攻略（MR流星飞，萧然Q、魔法ZC目录等）的基建作业。</span></p><p><span id="source-block-G2fRzuNNA2geXllT7v8IME"></span></p><h3 id="附录-supporting-information" tabindex="-1">附录：Supporting Information <a class="header-anchor" href="#附录-supporting-information" aria-label="Permalink to &quot;附录：Supporting Information&quot;">​</a></h3><p><span id="source-block-sXmHFgtj4mn8yE1gANNnzi"></span></p><h4 id="附录一-各阶段划分-各节点关键信息-最低矿物产出情况-对应建设等级-以及注意事项" tabindex="-1">附录一：各阶段划分，各节点关键信息，最低矿物产出情况，对应建设等级，以及注意事项 <a class="header-anchor" href="#附录一-各阶段划分-各节点关键信息-最低矿物产出情况-对应建设等级-以及注意事项" aria-label="Permalink to &quot;附录一：各阶段划分，各节点关键信息，最低矿物产出情况，对应建设等级，以及注意事项&quot;">​</a></h4><table tabindex="0"><thead><tr><th>资源产出</th><th></th><th></th><th></th><th></th><th></th><th></th><th></th><th></th><th>阶段划分</th></tr></thead><tbody><tr><td>阶段</td><td>剧情进度（完成到）</td><td>建设等级</td><td>源矿</td><td>蓝铁矿</td><td>赤铜矿</td><td>惰气</td><td>息壤气</td><td>备注</td><td></td></tr><tr><td>1</td><td>景玉谷据点</td><td>2</td><td>250</td><td>60</td><td>0</td><td>0</td><td>0</td><td>-</td><td>阶段1-准备期</td></tr><tr><td>2</td><td>清波寨</td><td>3</td><td>290</td><td>90</td><td>40</td><td>0</td><td>0</td><td>补武陵矿机</td><td><u>阶段2-过度期1</u></td></tr><tr><td>3</td><td>首墩据点+面具传送带</td><td>5</td><td>360</td><td>90</td><td>120</td><td>0</td><td>0</td><td>补景玉谷、清波寨矿机</td><td></td></tr><tr><td>4</td><td>北部禁区开门+应龙关据点</td><td>6</td><td>360</td><td>90</td><td>120</td><td>420</td><td>0</td><td>补各据点惰气</td><td><u>阶段3-过度期2</u></td></tr><tr><td>5</td><td>主线结束</td><td>7</td><td>360</td><td>90</td><td>220</td><td>460</td><td>30</td><td>-</td><td></td></tr><tr><td>6</td><td>藏剑谷结束</td><td>7</td><td>360</td><td>90</td><td>240</td><td>460</td><td>30</td><td>可能需要爆炸物（理论够用）；需要液化重息壤解锁矿点</td><td><u>阶段4-补充期1</u></td></tr><tr><td>7</td><td>试验园区</td><td>7</td><td>380</td><td>90</td><td>260</td><td>460</td><td>30</td><td>刚需液化重息壤进入区域</td><td></td></tr><tr><td>8</td><td>雪松林</td><td>7</td><td>380</td><td>90</td><td>310</td><td>460</td><td>80</td><td></td><td></td></tr><tr><td>9</td><td>填隙驻地</td><td>7</td><td>380</td><td>90</td><td>310</td><td>460</td><td>120</td><td></td><td></td></tr><tr><td>10</td><td>全部设施解锁，并升级10w调度券以下设施</td><td>10</td><td>500</td><td>90</td><td>330</td><td>460</td><td>120</td><td>资源回收全满级；武陵仓储节点2级；景玉谷物资调度2级；其余全部1级</td><td><u>阶段5-补充期2</u></td></tr><tr><td>11</td><td>全部设施解锁，并升级30w调度券以下设施</td><td>15</td><td>540</td><td>90</td><td>390</td><td>460</td><td>120</td><td>补充：三个据点升级到2级</td><td></td></tr></tbody></table><table tabindex="0"><thead><tr><th>问题汇总</th><th></th><th></th><th></th><th></th><th></th><th></th><th></th><th></th></tr></thead><tbody><tr><td>1</td><td>前期卡装备严重，无法制作高晶装备，只有权限等级28级后的升级会给一些，速通玩家可能会卡在这里</td><td></td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>2</td><td>物资调度终端的解锁，需要四号谷地的任务，可能会影响地区建设等级提升</td><td></td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>3</td><td>支线开图任务对科技树有一定要求，比如解锁更多天有烘炉及重息壤，想要只放两三次蓝图比较困难，需要小插件</td><td></td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>4</td><td>息壤逻辑链比较琐碎：单炉-双炉-4炉-重息壤、8炉-支线实验园区-12炉；解锁气体氛围机-新12息壤</td><td></td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>5</td><td>最核心的产能之一是灼铜，但需要大量科技点，可以考虑科技点规划教程？</td><td></td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>6</td><td>炮台相关一共9个工业点，可以先不点，多口暗管非刚需也可以不点</td><td></td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>7</td><td>景玉谷据点升级非常缓慢，但需求产品非常低级（低容电池、小药）不能只考虑产能，还要考虑产物</td><td></td><td></td><td></td><td></td><td></td><td></td><td></td></tr></tbody></table><p><span id="source-block-mpyQnWNl21Spw9V57lsmRt"></span></p><h4 id="附录二-基建区域升级价格、设施升级价格、据点调度券产出" tabindex="-1">附录二：基建区域升级价格、设施升级价格、据点调度券产出 <a class="header-anchor" href="#附录二-基建区域升级价格、设施升级价格、据点调度券产出" aria-label="Permalink to &quot;附录二：基建区域升级价格、设施升级价格、据点调度券产出&quot;">​</a></h4><table tabindex="0"><thead><tr><th>基建区域升级（单位：w调度券）</th><th></th><th></th><th></th><th></th><th></th><th></th><th></th><th></th></tr></thead><tbody><tr><td>项目</td><td>位置</td><td>区域扩大1</td><td>区域扩大2</td><td>存取线1</td><td>存取线2</td><td>存取线3</td><td>存取线4</td><td>存取线5</td></tr><tr><td>基地升级</td><td>武陵城</td><td>2</td><td>16</td><td>1</td><td>4</td><td>16</td><td>30</td><td>50</td></tr><tr><td></td><td>景玉谷</td><td>2</td><td>16</td><td>1</td><td>4</td><td>16</td><td>30</td><td></td></tr><tr><td></td><td>首墩</td><td>30</td><td>90</td><td>15</td><td>60</td><td>90</td><td>120</td><td></td></tr><tr><td></td><td>应龙关</td><td>45</td><td>120</td><td>30</td><td>80</td><td>120</td><td>160</td><td></td></tr></tbody></table><table tabindex="0"><thead><tr><th>武陵地区建设事务升级项目（单位：w调度券）</th><th></th><th></th><th></th><th></th><th></th></tr></thead><tbody><tr><td></td><td></td><td>解锁</td><td>升级到2</td><td>升级到3</td><td>升级到4</td></tr><tr><td>环境监测</td><td>武陵城</td><td>0</td><td>18.6</td><td>25</td><td>45</td></tr><tr><td></td><td>首墩</td><td>3</td><td>24</td><td>32</td><td>50</td></tr><tr><td>仓储节点</td><td>武陵城</td><td>1.25</td><td>7.2</td><td>15</td><td>90</td></tr><tr><td></td><td>试验园区</td><td>6</td><td>16</td><td>20</td><td>120</td></tr><tr><td>资源回收</td><td>武陵城</td><td>0.01</td><td>0.1</td><td>0.5</td><td>2</td></tr><tr><td></td><td>景玉谷1</td><td>0.01</td><td>0.1</td><td>0.5</td><td>2</td></tr><tr><td></td><td>景玉谷2</td><td>0.01</td><td>0.1</td><td>0.5</td><td>2</td></tr><tr><td></td><td>景玉谷3</td><td>0.01</td><td>0.1</td><td>0.5</td><td>2</td></tr><tr><td></td><td>清波寨</td><td>0.01</td><td>0.1</td><td>0.5</td><td>2</td></tr><tr><td>物资调度</td><td>景玉谷</td><td>0.5</td><td>6.4</td><td>45</td><td>140</td></tr><tr><td></td><td>首墩</td><td>3</td><td>40</td><td>65</td><td>100</td></tr><tr><td></td><td>应龙关</td><td>5</td><td>60</td><td>-</td><td>-</td></tr><tr><td>净水节点</td><td>试验园区</td><td>0</td><td>25</td><td>45</td><td>120</td></tr><tr><td>演武平台</td><td>藏剑谷</td><td>1</td><td>15</td><td>60</td><td></td></tr></tbody></table><table tabindex="0"><thead><tr><th>据点基础调度券产出（单位：调度券/min）</th><th></th><th></th><th></th><th></th><th>满配置</th></tr></thead><tbody><tr><td>地区</td><td>一级</td><td>二级</td><td>三级</td><td>四级</td><td>满配置</td></tr><tr><td>景玉谷</td><td>78</td><td>215</td><td>448</td><td>500</td><td>700</td></tr><tr><td></td><td>-</td><td>-</td><td>需要赤铜零件</td><td>-</td><td>-</td></tr><tr><td>首墩</td><td>55</td><td>140</td><td><span class="mark-green">325</span></td><td>380</td><td>456</td></tr><tr><td></td><td>-</td><td>-</td><td>-</td><td>-</td><td>-</td></tr><tr><td>应龙关</td><td>45</td><td>105</td><td>240</td><td>400</td><td>560</td></tr><tr><td></td><td>-</td><td>需要重息壤</td><td>-</td><td>需要灼铜零件</td><td>-</td></tr><tr><td>总和</td><td>178</td><td>460</td><td>1013</td><td>1280</td><td>1716</td></tr></tbody></table><p><span id="source-block-jn8x5dettrDbYELViSiKQO"></span></p><h4 id="附录三-水泵、气泵放置方法" tabindex="-1">附录三：水泵、气泵放置方法 <a class="header-anchor" href="#附录三-水泵、气泵放置方法" aria-label="Permalink to &quot;附录三：水泵、气泵放置方法&quot;">​</a></h4><p>首墩惰气</p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-d73e5e13c4ad6520.q90-97e1f96bcc5517d0.webp" alt="萌新入坑流程及注意事项「武陵篇」"></p><p>首墩水泵</p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-afc81a2914ca97bf.q90-08d897052a88fbc0.webp" alt="萌新入坑流程及注意事项「武陵篇」"></p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-00fab86e6a67bffc.q90-e7d05947834cb1d0.webp" alt="萌新入坑流程及注意事项「武陵篇」"></p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-b044d0831c1312f2.q90-8771eff965d7848c.webp" alt="萌新入坑流程及注意事项「武陵篇」"></p><p>首墩最左侧卡掉钓鱼佬的方法：在基建区域的右上角进入俯瞰模式，即可无视钓鱼佬放水泵</p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-43d368efaee205ce.q90-caac633ca3395547.webp" alt="萌新入坑流程及注意事项「武陵篇」"></p><p>本攻略未使用过景玉谷据点，但如果在最后更换为文档提到的完美分基地系列，需要使用景玉谷12息壤蓝图，水泵接法如下</p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-cc9b6fd280d3e7bb.q90-7c011072b4d27aa7.webp" alt="萌新入坑流程及注意事项「武陵篇」"></p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-3a9c58a636b3f02d.q90-5b8430800bd9efae.webp" alt="萌新入坑流程及注意事项「武陵篇」"></p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-78661be834f7b09e.q90-cf36e1af9158387b.webp" alt="萌新入坑流程及注意事项「武陵篇」"></p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-ba3467891e88e446.q90-2daf78b4bfde3c38.webp" alt="萌新入坑流程及注意事项「武陵篇」"></p></div>',1)])])}const b=d(i,[["render",c]]);export{m as __pageData,b as default};
